using System.Text;using System.Text.Json;
namespace LSE.AutoCADElectrical.Librarian;
public static class SettingsService {
 static readonly string Folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"LSE","AutoCADElectricalLibrarian");
 static readonly string FilePath=Path.Combine(Folder,"settings.json"); public static string SettingsPath=>FilePath; public static string LogFolder=>Path.Combine(Folder,"Logs");
 public const string DefaultStandardsRoot="C:\\_Lake_Shore_E_Vault\\CAD Standards\\AutoCAD\\ECAD Standards";
 public static AppSettings Load(){Directory.CreateDirectory(Folder);AppSettings s;try{s=File.Exists(FilePath)?JsonSerializer.Deserialize<AppSettings>(File.ReadAllText(FilePath))??new():new();}catch{s=new();}
  string root=DiscoverRoot();if(root.Length>0){Default(s,nameof(s.SymbolLibraryFolder),Path.Combine(root,"Symbol Library","LSE E-Cad Symbols"));Default(s,nameof(s.StockSymbolLibraryFolder),Path.Combine(root,"Symbol Library","NFPA"));Default(s,nameof(s.FootprintLibraryFolder),Path.Combine(root,"Footprint Library","LSE E-Cad Footprints"));Default(s,nameof(s.StockFootprintLibraryFolder),Path.Combine(root,"Footprint Library","panel"));Default(s,nameof(s.UserCircuitsFolder),Path.Combine(root,"User Circuits"));Default(s,nameof(s.IconMenuFolder),Path.Combine(root,"dat MENU"));Default(s,nameof(s.FootprintLookupPath),Path.Combine(root,"E-CAD .mbd ACCESS FILES","AeData","en-US","Catalogs","footprint_lookup.mdb"));Default(s,nameof(s.CatalogPath),Path.Combine(root,"E-CAD .mbd ACCESS FILES","AeData","en-US","Catalogs","default_cat.mdb"));}
  if(string.IsNullOrWhiteSpace(s.FootprintLookupPath))s.FootprintLookupPath=DiscoverAeData("footprint_lookup.mdb");if(string.IsNullOrWhiteSpace(s.CatalogPath))s.CatalogPath=DiscoverAeData("default_cat.mdb");
  if(string.IsNullOrWhiteSpace(s.LibraryStandardPath))s.LibraryStandardPath=Path.Combine(Path.GetDirectoryName(typeof(SettingsService).Assembly.Location)??"","LseLibraryStandard.json");if(string.IsNullOrWhiteSpace(s.BackupFolder))s.BackupFolder=Path.Combine(Folder,"Backups");
  if(string.IsNullOrWhiteSpace(s.NamingStandardPath))s.NamingStandardPath=Path.Combine(Path.GetDirectoryName(typeof(SettingsService).Assembly.Location)??"","LseNamingStandard.json");if(string.IsNullOrWhiteSpace(s.NamingWorkbookPath))s.NamingWorkbookPath=DiscoverWorkbook(root,s.CatalogPath);if(string.IsNullOrWhiteSpace(s.LsePartColumn))s.LsePartColumn="USER1";
  if(string.IsNullOrWhiteSpace(s.CompanyStandardsPath))s.CompanyStandardsPath=Path.Combine(Folder,"CompanyStandards.json");if(string.IsNullOrWhiteSpace(s.LsePartAttribute))s.LsePartAttribute="USER1";s.Favorites??=new();s.Recent??=new();
  if(string.IsNullOrWhiteSpace(s.SchematicMenuFile))s.SchematicMenuFile="ACE_NFPA_MENU.DAT";if(string.IsNullOrWhiteSpace(s.PanelMenuFile))s.PanelMenuFile="ACE_PANEL_MENU_NFPA.DAT";if(string.IsNullOrWhiteSpace(s.ImagesSubfolder))s.ImagesSubfolder="IMAGES";if(s.IconPixels<16)s.IconPixels=40;if(string.IsNullOrWhiteSpace(s.DefaultSeries))s.DefaultSeries="002";return s;}
 public static void Save(AppSettings s){Directory.CreateDirectory(Folder);string t=FilePath+".tmp";File.WriteAllText(t,JsonSerializer.Serialize(s,new JsonSerializerOptions{WriteIndented=true}));File.Move(t,FilePath,true);}
 static void Default(AppSettings s,string property,string value){var p=typeof(AppSettings).GetProperty(property)!;if(string.IsNullOrWhiteSpace(p.GetValue(s) as string))p.SetValue(s,value);}
 static string DiscoverRoot(){if(Directory.Exists(DefaultStandardsRoot))return DefaultStandardsRoot;try{foreach(var d in DriveInfo.GetDrives()){try{if(d.DriveType is not(DriveType.Fixed or DriveType.Network))continue;string p=Path.Combine(d.RootDirectory.FullName,"_Lake_Shore_E_Vault","CAD Standards","AutoCAD","ECAD Standards");if(Directory.Exists(p))return p;}catch{}}}catch{}return "";}
 // The parts catalog workbook: next to the catalog MDB or its parents, in the ECAD Standards root, or in Documents\AutoCAD_Electrical_2026.
 public static string DiscoverWorkbook(string root,string catalogPath){var candidates=new List<string>();try{string? d=catalogPath.Length>0?Path.GetDirectoryName(catalogPath):null;for(int i=0;i<5&&d is not null;i++){candidates.Add(Path.Combine(d,NamingWorkbookService.WorkbookFileName));d=Path.GetDirectoryName(d);}}catch{}
  if(root.Length>0){candidates.Add(Path.Combine(root,NamingWorkbookService.WorkbookFileName));candidates.Add(Path.Combine(root,"E-CAD .mbd ACCESS FILES",NamingWorkbookService.WorkbookFileName));}candidates.Add(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"AutoCAD_Electrical_2026",NamingWorkbookService.WorkbookFileName));
  foreach(string c in candidates)try{if(File.Exists(c))return c;}catch{}return "";}
 static string DiscoverAeData(string file){string d=Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);foreach(string v in new[]{"Acade 2026","Acade 2025"}){string p=Path.Combine(d,v,"AeData","en-US","Catalogs",file);if(File.Exists(p))return p;}return "";}
 public static List<string> ApplyProject(AppSettings s,string wdpPath){if(!File.Exists(wdpPath))throw new FileNotFoundException("Project file was not found.",wdpPath);var x=new List<string>();var o=ReadOptions(wdpPath);
  if(o.TryGetValue(1,out var sym)){var paths=Split(sym);string? lse=paths.FirstOrDefault(p=>p.Contains("LSE",StringComparison.OrdinalIgnoreCase)),stock=paths.FirstOrDefault(p=>Path.GetFileName(p.TrimEnd('\\')).Equals("NFPA",StringComparison.OrdinalIgnoreCase))??paths.FirstOrDefault();if(lse is not null){s.SymbolLibraryFolder=lse;x.Add("Symbol library: "+lse);}if(stock is not null&&!stock.Equals(lse,StringComparison.OrdinalIgnoreCase)){s.StockSymbolLibraryFolder=stock;x.Add("Stock symbol library: "+stock);}}
  if(o.TryGetValue(2,out var smenu)&&smenu.Trim().Length>0){s.IconMenuFolder=Path.GetDirectoryName(smenu.Trim())??s.IconMenuFolder;s.SchematicMenuFile=Path.GetFileName(smenu.Trim());x.Add("Schematic icon menu: "+smenu.Trim());}
  if(o.TryGetValue(3,out var fp)){var paths=Split(fp);string? lse=paths.FirstOrDefault(p=>p.Contains("LSE",StringComparison.OrdinalIgnoreCase)),stock=paths.FirstOrDefault(p=>!p.Contains("LSE",StringComparison.OrdinalIgnoreCase));if(lse is not null){s.FootprintLibraryFolder=lse;x.Add("Footprint library: "+lse);}if(stock is not null){s.StockFootprintLibraryFolder=stock;x.Add("Stock footprint library: "+stock);}}
  if(o.TryGetValue(4,out var pmenu)&&pmenu.Trim().Length>0){string f=Path.GetDirectoryName(pmenu.Trim())??"";if(f.Length>0&&!f.Equals(s.IconMenuFolder,StringComparison.OrdinalIgnoreCase))x.Add("NOTE: the panel icon menu lives in a different folder ("+f+"); the Librarian uses one icon menu folder: "+s.IconMenuFolder);s.PanelMenuFile=Path.GetFileName(pmenu.Trim());x.Add("Panel icon menu: "+pmenu.Trim());}
  s.ReferenceProjectPath=wdpPath;if(x.Count==0)x.Add("The project file has no +[1]..+[4] library lines; nothing changed.");return x;}
 static List<string> Split(string v)=>v.Split(';',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).ToList();
 public static Dictionary<int,string> ReadOptions(string wdpPath){var x=new Dictionary<int,string>();byte[] b=File.ReadAllBytes(wdpPath);Encoding e=b.Length>=2&&b[0]==0xFF&&b[1]==0xFE?Encoding.Unicode:b.Length>=2&&b[0]==0xFE&&b[1]==0xFF?Encoding.BigEndianUnicode:Encoding.UTF8;foreach(string raw in e.GetString(b).Split('\n')){string l=raw.Trim('\r',' ','\t','\uFEFF');var m=System.Text.RegularExpressions.Regex.Match(l,@"^\+\[(\d+)\](.*)$");if(m.Success)x[int.Parse(m.Groups[1].Value)]=m.Groups[2].Value;}return x;}
}
public static class LibraryStandardService {
 static readonly JsonSerializerOptions Options=new(){PropertyNameCaseInsensitive=true,ReadCommentHandling=JsonCommentHandling.Skip,AllowTrailingCommas=true};
 public static LibraryStandard Load(string path){if(!File.Exists(path))throw new FileNotFoundException("The LSE library standard JSON was not found. Point Settings at a shared copy or restore config\\LseLibraryStandard.json next to the plugin.",path);var t=JsonSerializer.Deserialize<LibraryStandard>(File.ReadAllText(path),Options)??throw new InvalidOperationException("The library standard JSON is empty.");
  t.Kinds=new(t.Kinds,StringComparer.OrdinalIgnoreCase);t.Series=new(t.Series,StringComparer.OrdinalIgnoreCase);t.SymbolFamilies=new(t.SymbolFamilies,StringComparer.OrdinalIgnoreCase);foreach(LibraryKind k in Enum.GetValues<LibraryKind>())if(!t.Kinds.ContainsKey(k.ToString()))throw new InvalidOperationException("The library standard JSON has no \"kinds."+k+"\" section.");
  foreach(var r in t.Kinds.Values){if(r.NamePattern.Length==0)throw new InvalidOperationException("Kind "+r.DisplayName+" has no namePattern.");try{_=new System.Text.RegularExpressions.Regex(r.NamePattern);}catch(Exception ex){throw new InvalidOperationException("Kind "+r.DisplayName+" has an invalid namePattern: "+ex.Message);}if(!r.ActionTemplate.Contains("{PATH}",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Kind "+r.DisplayName+": actionTemplate must contain {PATH}.");if(r.MaxNameLength<8)r.MaxNameLength=64;}
  if(string.IsNullOrWhiteSpace(t.ImagePrefix))t.ImagePrefix="IMAGES\\";t.Source=path;return t;}
}
